call:
api<{ notice: string }>(
        "/api/invitations/register",
        {
          token,
          email: form.get("email"),
          password: form.get("password"),
          fullName: form.get("fullName"),
        },
      )

api<{
        data?: unknown;
        invitationUrl?: string;
        pendingApproval?: boolean;
      }>(isNotification ? "/api/admin/notifications" : "/api/admin", {
        ...(scoped ? { careRecipientId: patientId } : {}),
        ...payload,
      })

api<{
        data: { status: string };
        invitationUrl?: string;
      }>("/api/patient-settings", {
        careRecipientId: patientId,
        kind,
        change,
        idempotencyKey: crypto.randomUUID(),
        expectedVersion:
          kind === "settings"
            ? (editingVersion ?? data.data.version)
            : (currentVersionRef.current ?? data.data.version),
        ...(requestId ? { requestId, decision } : {}),
      })

api("/api/profile", {
        action,
        ...(action === "email"
          ? { email: form.get("email") }
          : {
              phone: number,
              ...(action === "verifyPhone" ? { token: form.get("token") } : {}),
            }),
      })

api<{ data: SupplyDocument }>("/api/documents", {
          careRecipientId: context.patient!.id,
          type: "BAL",
          payload: {
            lines: catalog.map((product) => ({
              productId: product.id,
              quantity: "0",
            })),
            notes: "",
          },
          idempotencyKey,
          draft: true,
        })

api<{
      data: { product_id: string; name: string; base_quantity: string }[];
    }>(
      "/api/catalog/presentations?careRecipientId=" +
        context.patient!.id +
        "&barcode=" +
        encodeURIComponent(code),
    )

api(
        `/api/requisitions/${id}/${operation === "cancel" ? "status" : operation}`,
        operation === "science"
          ? { mode: "express", expectedVersion: data.progress.version }
          : operation === "cancel"
            ? { status: "cancelled", reason }
            : { reason },
        undefined,
        operation === "cancel" ? "PATCH" : "POST",
      )

